let rawOrders       = [];
let stockData       = [];
let inPurchaseItems = [];
let sentItems       = [];

try { rawOrders       = $('Get Pending Orders').all().map(i => i.json);       } catch(e) {}
try { stockData       = $('Get Stock Data').all().map(i => i.json);           } catch(e) {}
try { inPurchaseItems = $('Get In-Purchase Items').all().map(i => i.json);    } catch(e) {}
try { sentItems       = $('Get Quotation Sent Items').all().map(i => i.json); } catch(e) {}

if (!Array.isArray(rawOrders))       rawOrders       = rawOrders?.data       ?? [];
if (!Array.isArray(stockData))       stockData       = stockData?.data       ?? [];
if (!Array.isArray(inPurchaseItems)) inPurchaseItems = inPurchaseItems?.data ?? [];
if (!Array.isArray(sentItems))       sentItems       = sentItems?.data       ?? [];

if (rawOrders.length === 0) {
  console.log('[OrderCheck] No pending orders found.');
  return [{ json: { items: [], items_found: false, reason: 'no_pending_orders' } }];
}

if (stockData.length === 0) {
  console.log('[OrderCheck] No stock data returned.');
  return [{ json: { items: [], items_found: false, reason: 'no_stock_data' } }];
}

// Build stock map
const stockMap = new Map();
for (const s of stockData) stockMap.set(Number(s.icode), s);

const inPurchaseIcodes = new Set(inPurchaseItems.map(i => Number(i.icode)));
const sentIcodes = new Set(
  sentItems.filter(i => i.quotation_sent === true).map(i => Number(i.icode))
);

// Aggregate ordered qty + sono/soid per icode
const orderQtyByIcode  = new Map();
const orderSonoByIcode = new Map();
const orderSoidByIcode = new Map();

for (const order of rawOrders) {
  const items = Array.isArray(order.items) ? order.items
              : Array.isArray(order)        ? order
              : [];
  for (const item of items) {
    const icode = Number(item.icode);
    const qty   = Number(item.quantity ?? 0);
    orderQtyByIcode.set(icode, (orderQtyByIcode.get(icode) || 0) + qty);

    if (order.sono) {
      if (!orderSonoByIcode.has(icode)) orderSonoByIcode.set(icode, new Set());
      orderSonoByIcode.get(icode).add(String(order.sono));
    }
    if (order.soid) {
      if (!orderSoidByIcode.has(icode)) orderSoidByIcode.set(icode, new Set());
      orderSoidByIcode.get(icode).add(String(order.soid));
    }
  }
}

const result   = [];
const addedSet = new Set();

for (const [icode, totalOrderQty] of orderQtyByIcode) {
  if (inPurchaseIcodes.has(icode)) continue;
  if (sentIcodes.has(icode))       continue;
  if (addedSet.has(icode))         continue;

  const stock        = stockMap.get(icode);
  const availableQty = Number(stock?.available_qty    ?? 0);
  const min          = Number(stock?.minimum_threshold ?? 0);
  const projectedQty = availableQty - totalOrderQty;

  const isAlreadyLow  = availableQty <= min;
  const willBeLow     = projectedQty  <  min;
  const noStockRecord = !stock;

  if (isAlreadyLow || willBeLow || noStockRecord) {
    const raw = Math.max(min - projectedQty, 0) + totalOrderQty;
    const required_to_reach_min = Math.ceil(raw * 100) / 100;
    if (required_to_reach_min <= 0) continue;

    const sono = orderSonoByIcode.has(icode)
      ? [...orderSonoByIcode.get(icode)].join(', ') : null;
    const soid = orderSoidByIcode.has(icode)
      ? [...orderSoidByIcode.get(icode)].join(', ') : null;

    result.push({
      icode,
      item_name            : stock?.iname ?? stock?.item_name ?? `Item ${icode}`,
      required_to_reach_min,
      uom                  : stock?.uom ?? 'PCS',
      available_qty        : availableQty,
      minimum_threshold    : min,
      projected_after_order: projectedQty,
      total_order_qty      : totalOrderQty,
      flag_reason          : noStockRecord ? 'no_stock_record'
                           : isAlreadyLow  ? 'already_low'
                           : 'will_be_low',
      sono,
      soid
    });
    addedSet.add(icode);
  }
}

const items_found = result.length > 0;
console.log(`[OrderCheck] ${result.length} items flagged. items_found=${items_found}`);

return [{ json: { items: result, items_found, reason: items_found ? 'flagged_items_found' : 'all_stock_sufficient' } }];

// items_found = true — pass items to Vendor Quoting Workflow
const items = $json.items;
console.log(`[OrderCheck] Sending ${items.length} items to Vendor Quoting Workflow.`);
return [{ json: { items } }];

// items_found = false — log and stop
const reason = $json.reason ?? 'all_stock_sufficient';
console.log(`[OrderCheck] Stopped: ${reason}`);
return [{ json: { status: 'stopped', reason } }];
